    if self.on_ask_tab {
        return (
            Conversation::Questions,
            self.ask_session_epoch,
            &self.ask_session,
        );
    }
    let lane = tab_lanes(self.selected_mode)
        .first()
        .copied()
        .unwrap_or(Lane::Code);
    (
        usage_conversation(lane),
        *self.session_epoch.of(lane),
        self.session.of(lane),
    )
}

