        preview: &PreviewPrompt,
        cx: &mut Context<Self>,
    ) {
        let id = preview.id;
        let Some(project_dir) = self.project_dir.clone() else {
            input.update(cx, |input, cx| {
                input.set_preview(id, Err("Open a project to preview the prompt.".into()), cx)
